WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY monthly_fee NULLS LAST, id) AS dedup_rank FROM subscriptions QUALIFY dedup_rank = 1) SELECT DATE_TRUNC('YEAR', end_date) AS year_start, CASE WHEN monthly_fee >= 214 THEN 'HIGH' ELSE 'LOW' END AS monthly_fee_tier, SUM(CASE WHEN status = 'PAUSED' THEN monthly_fee ELSE 0 END) AS paused_monthly_fee, COUNT_IF(status = 'PAUSED') AS paused_events, APPROX_PERCENTILE(monthly_fee, 0.95) AS monthly_fee_p95 FROM ranked GROUP BY 1, 2 HAVING SUM(CASE WHEN status = 'PAUSED' THEN monthly_fee ELSE 0 END) < 1000000 ORDER BY monthly_fee_tier DESC NULLS FIRST
